def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value in (2, 8)]
        if not marks:
            continue
        for i, c in enumerate(marks):
            end = marks[i + 1] if i + 1 < len(marks) else w - 1
            length = end - c
            for k in range(length):
                rr = r - 1 - k
                if rr < 0:
                    break
                out[rr][c] = row[c] if k == length - 1 else 1
        break
    return out
